import axios from '@/utils/axiosConfig';
import { useConfirm } from 'primevue/useconfirm';
export default {
  name: 'WorkflowBuilder',
  setup() {
    return {
      $confirm: useConfirm()
    };
  },
  props: {
    taskId: {
      type: Number,
      default: null
    },
    modelValue: {
      type: Array,
      default: () => []
    },
    projectStatus: {
      type: String,
      default: null
    },
    showCompleteButton: {
      type: Boolean,
      default: false
    }
  },
  emits: ['update:modelValue'],
  data() {
    return {
      steps: [],
      users: [],
      projectStatusOptions: [],
      stepTypeOptions: [{
        label: 'ทั่วไป',
        value: 'general',
        color: '#6b7280'
      }, {
        label: 'จัดซื้อ',
        value: 'procurement',
        color: '#8b5cf6'
      }],
      showStepDialog: false,
      editingIndex: null,
      dragIndex: null,
      dragOverIndex: null,
      currentStep: {
        step_name: '',
        description: '',
        start_date: null,
        end_date: null,
        assigned_users: [],
        step_order: 0
      },
      // Template
      templates: [],
      saveTemplateDialog: false,
      loadTemplateDialog: false,
      templateName: '',
      templateDesc: ''
    };
  },
  watch: {
    steps: {
      deep: true,
      handler(val) {
        if (!this.taskId) {
          localStorage.setItem('workflow_steps_draft', JSON.stringify(val));
        }
      }
    },
    currentStep: {
      deep: true,
      handler(val) {
        if (this.showStepDialog) {
          localStorage.setItem('workflow_step_draft', JSON.stringify(val));
        }
      }
    },
    modelValue: {
      immediate: true,
      handler(val) {
        this.steps = val || [];
      }
    },
    taskId: {
      immediate: true,
      handler(val) {
        if (val) {
          this.loadSteps();
        }
      }
    }
  },
  mounted() {
    this.loadUsers();
    this.loadStatusOptions();
    if (!this.taskId) {
      const draft = localStorage.getItem('workflow_steps_draft');
      if (draft) {
        try {
          const d = JSON.parse(draft);
          if (d && d.length) {
            this.steps = d;
            this.$emit('update:modelValue', d);
          }
        } catch (e) {
          localStorage.removeItem('workflow_steps_draft');
        }
      }
    }
  },
  methods: {
    async loadStatusOptions() {
      try {
        const response = await axios.get('/api/settings/statuses');
        this.projectStatusOptions = response.data;
      } catch {
        // ignore
      }
    },
    getEmptyStep() {
      return {
        step_name: '',
        description: '',
        start_date: null,
        end_date: null,
        assigned_users: [],
        project_statuses: [],
        step_type: 'general',
        step_order: this.steps.length
      };
    },
    async loadUsers() {
      try {
        const response = await axios.get('/api/users');
        this.users = response.data.map(u => ({
          id: u.id,
          name: `${u.firstname} ${u.lastname}${u.nickname ? ` (${u.nickname})` : ''}`,
          position: u.position || '',
          department: u.department || ''
        }));
      } catch (error) {
        console.error('Error loading users:', error);
      }
    },
    async loadSteps() {
      if (!this.taskId) return;
      try {
        const response = await axios.get(`/api/task-steps/task/${this.taskId}`);
        this.steps = response.data;
        this.$emit('update:modelValue', this.steps);
      } catch (error) {
        console.error('Error loading steps:', error);
      }
    },
    addStep() {
      const draft = localStorage.getItem('workflow_step_draft');
      this.currentStep = draft ? JSON.parse(draft) : this.getEmptyStep();
      this.editingIndex = null;
      this.showStepDialog = true;
    },
    editStep(index) {
      this.currentStep = {
        ...this.steps[index]
      };
      // Convert date strings to Date objects
      if (this.currentStep.start_date) {
        this.currentStep.start_date = new Date(this.currentStep.start_date);
      }
      if (this.currentStep.end_date) {
        this.currentStep.end_date = new Date(this.currentStep.end_date);
      }
      // Map assigned_users to match dropdown options by id
      if (this.currentStep.assigned_users && this.currentStep.assigned_users.length > 0) {
        this.currentStep.assigned_users = this.currentStep.assigned_users.map(u => {
          const userId = typeof u === 'object' ? u.id : u;
          return this.users.find(user => user.id === userId);
        }).filter(Boolean);
      }
      this.editingIndex = index;
      this.showStepDialog = true;
    },
    clearDraft() {
      localStorage.removeItem('workflow_steps_draft');
      localStorage.removeItem('workflow_step_draft');
    },
    saveStep() {
      const existingStep = this.editingIndex !== null ? this.steps[this.editingIndex] : {};
      const stepData = {
        ...existingStep,
        ...this.currentStep,
        step_order: this.editingIndex !== null ? this.editingIndex : this.steps.length,
        start_date: this.currentStep.start_date ? this.formatDate(this.currentStep.start_date) : null,
        end_date: this.currentStep.end_date ? this.formatDate(this.currentStep.end_date) : null
      };
      if (this.editingIndex !== null) {
        this.steps[this.editingIndex] = stepData;
      } else {
        this.steps.push(stepData);
      }
      this.$emit('update:modelValue', this.steps);
      localStorage.removeItem('workflow_step_draft');
      this.showStepDialog = false;
    },
    onDragStart(event, index) {
      this.dragIndex = index;
      event.dataTransfer.effectAllowed = 'move';
    },
    onDragEnter(event, index) {
      if (this.dragIndex !== index) {
        this.dragOverIndex = index;
      }
    },
    onDragLeave() {
      this.dragOverIndex = null;
    },
    onDrop(event, index) {
      event.preventDefault();
      if (this.dragIndex !== null && this.dragIndex !== index) {
        const item = this.steps.splice(this.dragIndex, 1)[0];
        this.steps.splice(index, 0, item);
        // Update step_order
        this.steps.forEach((step, idx) => {
          step.step_order = idx;
        });
        this.$emit('update:modelValue', this.steps);
      }
      this.dragIndex = null;
      this.dragOverIndex = null;
    },
    deleteStep(index) {
      this.$confirm.require({
        message: 'คุณต้องการลบ step นี้หรือไม่?',
        header: 'ยืนยันการลบ',
        icon: 'pi pi-exclamation-triangle',
        accept: () => {
          this.steps.splice(index, 1);
          // Update step_order
          this.steps.forEach((step, idx) => {
            step.step_order = idx;
          });
          this.$emit('update:modelValue', this.steps);
        }
      });
    },
    async completeStep(index) {
      const step = this.steps[index];
      if (step.id && this.taskId) {
        try {
          await axios.put(`/api/task-steps/${step.id}`, {
            status: 'completed'
          });
          this.steps[index].status = 'completed';
          this.$emit('update:modelValue', this.steps);
        } catch (error) {
          console.error('Error completing step:', error);
        }
      } else {
        this.steps[index].status = 'completed';
        this.$emit('update:modelValue', this.steps);
      }
    },
    formatDate(date) {
      if (!date) return null;
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    },
    formatDateRange(start, end) {
      if (!start && !end) return 'ไม่ระบุวันที่';
      const formatThai = date => {
        if (!date) return '';
        return new Date(date).toLocaleDateString('th-TH', {
          day: 'numeric',
          month: 'short',
          year: '2-digit'
        });
      };
      if (start && end) {
        return `${formatThai(start)} - ${formatThai(end)}`;
      }
      return formatThai(start || end);
    },
    formatCompletedDate(date) {
      if (!date) return '';
      return new Date(date).toLocaleDateString('th-TH', {
        day: 'numeric',
        month: 'short',
        year: '2-digit'
      });
    },
    getStatusIcon(step) {
      if (step.status === 'completed') return 'pi pi-check-circle';
      if (step.status === 'in_progress') return 'pi pi-spin pi-spinner';
      return 'pi pi-circle';
    },
    getStepStatusLabel(step) {
      if (step.status === 'completed') return 'เสร็จสิ้น';
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      // เกินกำหนด - เช็คก่อนเสมอ (priority สูงสุด)
      if (step.end_date) {
        const endDate = new Date(step.end_date);
        endDate.setHours(0, 0, 0, 0);
        if (today > endDate) return 'เกินกำหนด';
      }

      // กำลังดำเนินการ - เช็คว่ามีการลงงานแล้ว
      if (step.has_work_logged) {
        if (step.latest_work_date) {
          const workDate = new Date(step.latest_work_date);
          workDate.setHours(0, 0, 0, 0);
          if (workDate <= today) return 'กำลังดำเนินการ';
        } else {
          return 'กำลังดำเนินการ';
        }
      }
      return 'รอดำเนินการ';
    },
    getStepClass(step) {
      if (step.status === 'completed') return 'status-completed';
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      // เกินกำหนด - เช็คก่อนเสมอ (priority สูงสุด)
      if (step.end_date) {
        const endDate = new Date(step.end_date);
        endDate.setHours(0, 0, 0, 0);
        if (today > endDate) return 'status-overdue';
      }

      // กำลังดำเนินการ - เช็คว่ามีการลงงานแล้ว
      if (step.has_work_logged) {
        if (step.latest_work_date) {
          const workDate = new Date(step.latest_work_date);
          workDate.setHours(0, 0, 0, 0);
          if (workDate <= today) return 'status-working';
        } else {
          return 'status-working';
        }
      }
      return 'status-pending';
    },
    getProjectStatusLabel(status) {
      const found = this.projectStatusOptions.find(opt => opt.value === status);
      return found ? found.label : status;
    },
    getStatusColor(status) {
      const found = this.projectStatusOptions.find(opt => opt.value === status);
      return found?.color || '#6b7280';
    },
    getStepTypeLabel(type) {
      const found = this.stepTypeOptions.find(opt => opt.value === type);
      return found ? found.label : 'ทั่วไป';
    },
    getStepTypeColor(type) {
      const found = this.stepTypeOptions.find(opt => opt.value === type);
      return found?.color || '#6b7280';
    },
    // Template methods
    async loadTemplates() {
      try {
        const res = await axios.get('/api/settings/workflow-templates');
        this.templates = res.data;
      } catch (e) {
        console.error(e);
      }
    },
    showSaveTemplate() {
      this.templateName = '';
      this.templateDesc = '';
      this.saveTemplateDialog = true;
    },
    async showLoadTemplate() {
      await this.loadTemplates();
      this.loadTemplateDialog = true;
    },
    async saveTemplate() {
      const cleanSteps = this.steps.map(s => ({
        step_name: s.step_name,
        description: s.description,
        project_statuses: s.project_statuses,
        step_type: s.step_type || 'general'
      }));
      try {
        await axios.post('/api/settings/workflow-templates', {
          name: this.templateName,
          description: this.templateDesc,
          steps: cleanSteps
        });
        this.saveTemplateDialog = false;
      } catch (e) {
        console.error(e);
      }
    },
    loadTemplate(t) {
      const newSteps = (t.steps || []).map((s, i) => ({
        ...s,
        step_order: i,
        assigned_users: [],
        start_date: null,
        end_date: null
      }));
      this.steps = newSteps;
      this.$emit('update:modelValue', this.steps);
      this.loadTemplateDialog = false;
    },
    async deleteTemplate(id) {
      this.$confirm.require({
        message: 'คุณต้องการลบ template นี้หรือไม่?',
        header: 'ยืนยันการลบ',
        icon: 'pi pi-exclamation-triangle',
        accept: async () => {
          try {
            await axios.delete(`/api/settings/workflow-templates/${id}`);
            this.templates = this.templates.filter(t => t.id !== id);
          } catch (e) {
            console.error(e);
          }
        }
      });
    }
  }
};
